// ── Eclipse Discipline Score — deterministic 0-100 scoring ──────────────────
// The score is generated by fixed rules, never by an LLM. AI may explain the
// score but must not determine it. The weights are versioned so the system can
// evolve without breaking historical scores.

import type { DisciplineBreakdown, TradeRecord } from "../types";

export const DISCIPLINE_VERSION = 1;

// Weight budget (sums to 100).
const WEIGHTS = { risk: 25, strategy: 25, stop: 20, overtrading: 15, execution: 15 };

export interface DisciplineOptions {
  /** Account size in currency — enables the true risk-per-trade rule. */
  accountSize?: number | null;
  /** Max fraction of the account risked per trade (e.g. 0.01 = 1%). */
  riskPerTrade?: number | null;
}

/**
 * Compute the Eclipse Discipline Score for a set of trades.
 *
 * Components:
 *  - Risk (25): fraction of trades respecting the configured risk-per-trade
 *    rule (account size × risk %). Falls back to a 1%-of-notional proxy when no
 *    account size is configured.
 *  - Strategy (25): fraction of trades that have a strategy/setup assigned
 *    (a proxy for "followed a plan").
 *  - Stop (20): fraction of trades with a stop loss set.
 *  - Overtrading (15): penalizes high trade counts relative to a healthy
 *    baseline (≤ 3 trades/day is ideal).
 *  - Execution (15): penalizes recorded mistakes (early exits, stop moves,
 *    target moves, partial exits, revenge/overtrade tags).
 */
export function computeDiscipline(trades: TradeRecord[], options: DisciplineOptions = {}): DisciplineBreakdown {
  const closed = trades.filter((t) => t.status === "closed");
  const n = closed.length;
  if (n === 0) {
    return { risk: 0, strategy: 0, stop: 0, overtrading: 0, execution: 0, total: 0 };
  }

  // Risk: trades whose risk respects the configured rule. When an account size
  // is known, the rule is riskAmount ≤ accountSize × riskPerTrade. Otherwise we
  // fall back to the historic 1%-of-notional proxy (stop within 1% of entry).
  const maxRisk = options.accountSize && options.accountSize > 0
    ? options.accountSize * (options.riskPerTrade && options.riskPerTrade > 0 ? options.riskPerTrade : 0.01)
    : null;
  const riskOk = closed.filter((t) => {
    if (t.riskAmount == null) return false;
    if (maxRisk != null) return t.riskAmount <= maxRisk;
    const notional = t.entry * t.quantity;
    return notional > 0 && t.riskAmount / notional <= 0.01;
  }).length;
  const risk = (riskOk / n) * WEIGHTS.risk;

  // Strategy: has a strategy or setup assigned.
  const withPlan = closed.filter((t) => t.strategyId || t.setupId).length;
  const strategy = (withPlan / n) * WEIGHTS.strategy;

  // Stop: has a stop loss.
  const withStop = closed.filter((t) => t.stopLoss != null).length;
  const stop = (withStop / n) * WEIGHTS.stop;

  // Overtrading: penalize days with too many trades.
  const byDay = new Map<string, number>();
  for (const t of closed) {
    const day = t.exitTime.slice(0, 10);
    byDay.set(day, (byDay.get(day) ?? 0) + 1);
  }
  let overtradingScore = WEIGHTS.overtrading;
  for (const count of byDay.values()) {
    if (count > 3) overtradingScore -= (count - 3) * 2;
  }
  const overtrading = Math.max(0, Math.min(WEIGHTS.overtrading, overtradingScore));

  // Execution: start full, subtract for recorded mistakes.
  let execution = WEIGHTS.execution;
  for (const t of closed) {
    const mistakes = parseMistakes(t);
    if (mistakes.length > 0) execution -= Math.min(WEIGHTS.execution, mistakes.length * 3);
    if (t.emotion === "Revenge" || t.emotion === "FOMO") execution -= 2;
  }
  const executionScore = Math.max(0, Math.min(WEIGHTS.execution, execution));

  const total = Math.round(risk + strategy + stop + overtrading + executionScore);
  return {
    risk: Math.round(risk),
    strategy: Math.round(strategy),
    stop: Math.round(stop),
    overtrading: Math.round(overtrading),
    execution: Math.round(executionScore),
    total,
  };
}

function parseMistakes(t: TradeRecord): string[] {
  if (!t.mistakes) return [];
  try {
    const arr = JSON.parse(t.mistakes) as string[];
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

/** Convenience: just the 0-100 number. */
export function disciplineScore(trades: TradeRecord[]): number {
  return computeDiscipline(trades).total;
}

/** Classify a day's discipline for the heatmap intensity. */
export function dayDiscipline(trades: TradeRecord[]): number | null {
  if (trades.length === 0) return null;
  return disciplineScore(trades);
}
